use crate::Point;
use crate::triangulation_2d;
let r = 1.0_f64;
let hex_pts: Vec<Point> = (0..6).map(|i| {
    let angle = i as f64 * PI / 3.0;
    Point::new(r * angle.cos(), r * angle.sin(), 0.0)
}).chain(std::iter::once({
    let angle = 0.0_f64;
    Point::new(r * angle.cos(), r * angle.sin(), 0.0)
})).collect();
let tris = triangulation_2d::triangulate(&hex_pts, None);

